<?php
declare(strict_types=1);
namespace Tests\Unit\Identity;
use App\Application\Identity\DTO\Request\ReplaceAvatarRequestDto;use App\Application\Identity\Port\{AvatarStorageInterface,StoredAvatar,TransactionManagerInterface};use App\Application\Identity\Service\ProfileAvatarService;use App\Domain\Identity\Entity\{User,UserAvatar};use App\Domain\Identity\Enum\AvatarSource;use App\Domain\Identity\Repository\UserRepositoryInterface;use PHPUnit\Framework\TestCase;
final class ProfileAvatarServiceTest extends TestCase {public function testManualAvatarReplacesOldAvatarOnlyAfterSavingUser():void{$old=new UserAvatar('user/old.webp','image/webp',AvatarSource::GOOGLE,new \DateTimeImmutable());$users=new ProfileAvatarUsers(new User('user','user@example.test','Pessoa',null,'ACTIVE',['USER'],$old));$storage=new ProfileAvatarStorage();$service=new ProfileAvatarService($users,$storage,new ProfileAvatarTransactions());$result=$service->replace(new ReplaceAvatarRequestDto('user',$this->png()));self::assertTrue($result->available);self::assertSame('image/webp',$result->mimeType);self::assertSame(AvatarSource::MANUAL,$users->findById('user')?->avatar?->source);self::assertSame(['user/old.webp'],$storage->removed);}public function testRejectsInvalidAvatarWithoutStoring():void{$storage=new ProfileAvatarStorage();$service=new ProfileAvatarService(new ProfileAvatarUsers(new User('user','user@example.test','Pessoa',null,'ACTIVE',['USER'])),$storage,new ProfileAvatarTransactions());$this->expectException(\InvalidArgumentException::class);try{$service->replace(new ReplaceAvatarRequestDto('user','invalid'));}finally{self::assertSame([], $storage->stored);}}private function png():string{$image=imagecreatetruecolor(32,32);ob_start();imagepng($image);$png=(string)ob_get_clean();imagedestroy($image);return$png;}}
final class ProfileAvatarUsers implements UserRepositoryInterface {public function __construct(private ?User $user){}public function findByEmail(string $email):?User{return$this->user?->email===$email?$this->user:null;}public function findById(string $id):?User{return$this->user?->id===$id?$this->user:null;}public function save(User $user):void{$this->user=$user;}public function list(int $offset,int $limit,?string $query,?string $status):array{return[];}public function count(?string $query,?string $status):int{return 0;}public function countActiveAdmins():int{return 0;}}
final class ProfileAvatarStorage implements AvatarStorageInterface {public array $stored=[];public array $removed=[];public function store(string $userId,string $contents,string $mimeType):StoredAvatar{$this->stored[]=$contents;return new StoredAvatar($userId.'/new.webp',$mimeType);}public function read(string $storageKey):?string{return null;}public function remove(string $storageKey):void{$this->removed[]=$storageKey;}}
final class ProfileAvatarTransactions implements TransactionManagerInterface {public function transactional(callable $callback):mixed{return$callback();}}
